css:
* { margin:0; padding:0; box-sizing:border-box; }

.slide {
  width: 1080px;
  height: 1350px;
  background: #000000;
  font-family: 'Inter', sans-serif;
  overflow: hidden;
  position: relative;
  padding: 100px 76px 0;
}

.header { display:flex; align-items:center; gap:27px; margin-bottom:52px; }
.avatar { width:110px; height:110px; border-radius:50%; overflow:hidden; background:#2a3a4a; flex-shrink:0; }
.avatar img { width:100%; height:100%; object-fit:cover; display:block; }
.user-info { display:flex; flex-direction:column; gap:4px; }
.name-row { display:flex; align-items:center; gap:10px; }
.name { font-size:36px; font-weight:700; color:#E7E9EA; line-height:1.2; }
.verified svg { width:31px; height:31px; display:block; flex-shrink:0; }
.vpath { fill:#1D9BF0; }
.handle { font-size:31px; color:#71767B; line-height:1.2; font-weight:400; }

.content { font-size:46px; line-height:1.45; color:#E7E9EA; font-weight:400; letter-spacing:-0.01em; }
.content p { margin:0 0 36px; }
.content p:last-child { margin-bottom:0; }
.content b { font-weight:700; }

.post-image { margin-top:44px; width:100%; height:480px; border-radius:22px; overflow:hidden; border:1px solid #2F3E4E; background:#000; }
.post-image img { width:100%; height:100%; display:block; object-fit:cover; object-position:center; }
